/**
 * CloudLLMConfig
 *
 * A hosted provider, reached with an API key.
 */
export type CloudLlmConfigWritable = {
  /**
   * Provider
   *
   * Who serves the model. Changing it clears the model names and the key.
   */
  provider: 'anthropic' | 'openai' | 'gemini'
  /**
   * Api Key
   *
   * Credential for a hosted provider. A local server usually needs none.
   */
  api_key?: string
  /**
   * Model Analysis
   *
   * Reads the prompt and picks the tracks. The stronger model belongs here.
   */
  model_analysis?: string
  /**
   * Model Generation
   *
   * Writes the playlist from the filtered list. A cheaper model does.
   */
  model_generation?: string
  /**
   * Smart Generation
   *
   * Spend the analysis model on generation too: better results, higher cost.
   */
  smart_generation?: boolean
  /**
   * Context Window
   *
   * Required: a per-model limits table goes stale, and a guessed one overflows.
   */
  context_window: number
  /**
   * Request Timeout
   *
   * Seconds before an outbound call is abandoned; slow hardware needs minutes.
   */
  request_timeout?: number
  /**
   * Stream Idle Timeout
   *
   * Seconds of silence on a generate stream before the browser gives up. Measured per frame: a model may think for minutes between them.
   */
  stream_idle_timeout?: number
  /**
   * Max Output Tokens
   *
   * Ceiling on one completion; raise it for models that answer at length.
   */
  max_output_tokens?: number
  /**
   * Max Retries
   *
   * Attempts per call, retried with exponential backoff.
   */
  max_retries?: number
  /**
   * Temperature
   *
   * Randomness. Unset sends nothing, leaving the server's own default.
   */
  temperature?: number | null
  /**
   * Top P
   *
   * Nucleus sampling mass. Unset sends nothing; the model card names a value.
   */
  top_p?: number | null
  /**
   * Top K
   *
   * Candidate tokens considered per step. Unset sends nothing.
   */
  top_k?: number | null
  /**
   * Min P
   *
   * Floor on a token's probability, relative to the best one. Unset sends nothing.
   */
  min_p?: number | null
  /**
   * Presence Penalty
   *
   * Pushes the model off tokens it has already used. Unset sends nothing.
   */
  presence_penalty?: number | null
  /**
   * Repetition Penalty
   *
   * Divides the score of repeated tokens. Unset sends nothing.
   */
  repetition_penalty?: number | null
  /**
   * Probe Timeout
   *
   * Seconds for a metadata-only liveness probe; slow here means server down.
   */
  probe_timeout?: number
  /**
   * Cost Analysis Input
   *
   * USD per million input tokens on the analysis model. 0 reports no cost.
   */
  cost_analysis_input?: number
  /**
   * Cost Analysis Output
   *
   * USD per million output tokens on the analysis model. 0 reports no cost.
   */
  cost_analysis_output?: number
  /**
   * Cost Generation Input
   *
   * USD per million input tokens on the generation model. 0 reports no cost.
   */
  cost_generation_input?: number
  /**
   * Cost Generation Output
   *
   * USD per million output tokens on the generation model. 0 reports no cost.
   */
  cost_generation_output?: number
}

